% interface to terminal command linefunction fBridge6(funcName,funcArgs)% always 'funcName' MUST be given% 'funcArgs' is an optional cell-array% input/output args of the targeted function are detected automaticallysilent_functions (1,"local");suppress_verbose_help_message(1,"local");[parDir,~,~] = fileparts (pwd);% find the parent foldersubDir = genpath(parDir);% all the sub foldersaddpath(subDir);% help for better searchclearvars('subDir','parDir');% free memoryif nargin==0	% called from terminal with m-file (no direct Args.)	callOpts = cmdline_options ();	callArgs = callOpts.remaining_args;% argumans sent through CMD call of m-file	% the 1st is the Bridge itself	% the 2nd is the targeted function name	funcName  = callArgs{2};	if numel(callArgs)>=3		funcArgs  = callArgs{3:end};		% funcArgs are all in string/char type		% so the numeric ones must be casted back to double/number		for i=1:numel(funcArgs)			funcArgs{i} = strRefiner(funcArgs{i});		end%for	endend%ifhasInput  = nargin(funcName);hasOutput = nargout(funcName);%% INPUT ---------------------------------------------------------------if hasInput==0	% not any input is passed (& required)elseif exist('funcArgs','var')	% input args are passed by value (during direct call)
elseif hasInput>0	% get the input argumans	colectedStr = '';% empty string for input data from colectedStrAL	%% get and combine strings into one	while true	%% read the input from terminal		terminalStr = fgets(stdin);		if terminalStr == -1			% nothing left to add			%% JSON is collected as string from CMD input			myData = jsondecode(colectedStr);% converted back to struct()			% find the input argumans			funcArgs = myData.args;% cell of anything			clearvars('colectedStr','terminalStr');% free memory			break;% exit		else			% continue to grab the data as input			colectedStr = [colectedStr,terminalStr];% append		end%if	end%whileend%if%% CALL--------------------------------------------------------------if hasOutput==0 && hasInput==0% neither input has been provided nor output is requested	feval(funcName);elseif hasOutput==0 && hasInput>0% no output is requested	feval(funcName,funcArgs{:});% input onlyelseif hasOutput>0 && hasInput==0% no input is provided but the output is expected	[logStr,retVal]  = evalc([funcName,'()']);% output onlyelseif hasOutput>0 && hasInput>0% both input and output	[logStr,retVal]  = evalc([funcName,'(funcArgs{:})'])% output & inputelse% never	error(['h-case{ input No=',num2str(hasOutput),'} {output No=',num2str(hasOutput),'}']);end%if%% RETURN -----------------------------------------------------------if hasOutput>0	silent_functions (0,"local");	jData = jsonencode(retVal);	printf("%s", jData);% send back to terminal	end%ifend%function%% SUB FUNCTIONs ----------------------------------------------------function z = strRefiner(s)	n = str2double(s);	if isnan(n)		z = s;% remain as string	else		z = n;% cast to number	end%if
end%function